/* board_data.h - the boards as plain tables (generated by tools/kicad2c.py
 * into c64_board_data.c, zx48_board_data.c). Coordinates are in
 * millimeters, x to the right, y down, as in KiCad. */
#ifndef BOARD_DATA_H
#define BOARD_DATA_H

typedef struct {
    const char *name;       /* pad name: "1".."40" for ICs, letters on some connectors */
    float x, y;             /* absolute center position (mm) */
    float w, h;             /* pad size (mm) */
    int net;                /* index into the nets, or -1 if unconnected */
} bd_pad_t;

typedef struct {
    const char *ref;        /* "U17" */
    const char *value;      /* "PLA_U17", "3K3", ... */
    const char *footprint;  /* KiCad footprint name */
    int first_pad, npads;   /* range in the pads */
} bd_comp_t;

/* A board: its outline, nets, pads and parts. */
typedef struct {
    float outline[4];       /* x0, y0, x1, y1 of the board edge */
    const char *const *nets; int nnets;
    const bd_pad_t *pads; int npads;    /* the pads of each part are consecutive */
    const bd_comp_t *comps; int ncomps;
} board_data_t;

extern const board_data_t bd_c64;   /* c64_board_data.c */
extern const board_data_t bd_c64c;  /* c64c_board_data.c (ASSY 250469) */
extern const board_data_t bd_zx48;  /* zx48_board_data.c (Issue 3B) */
extern const board_data_t bd_zx48i2;    /* zx48i2_board_data.c (Issue 2) */
extern const board_data_t bd_zx48i1;    /* zx48i1_board_data.c (Issue 1) */
extern const board_data_t bd_zx48i4b;   /* zx48i4b_board_data.c (Issue 4B) */
extern const board_data_t bd_zx48i6a;   /* zx48i6a_board_data.c (Issue 6A) */

#endif
